import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { useNavigate } from "react-router-dom";

export default function Match() {
  const [entryFee, setEntryFee] = useState(null);
  const [status, setStatus] = useState("");
  const [loading, setLoading] = useState(false);
  const [playerProfiles, setPlayerProfiles] = useState({ self: {}, opponent: {} });
  const [showPlayers, setShowPlayers] = useState(false);
  const [slideshowIndex, setSlideshowIndex] = useState(0);

  // ** New: Two separate countdown states for player1 and player2 **
  const [countdownP1, setCountdownP1] = useState(null);
  const [countdownP2, setCountdownP2] = useState(null);

  const navigate = useNavigate();
  const stompClientRef = useRef(null);
  const slideshowRef = useRef(null);
  // separate countdown timers for p1 and p2
  const countdownRefP1 = useRef(null);
  const countdownRefP2 = useRef(null);

  const ALLOWED_FEES = [13, 23, 50];
  const token = localStorage.getItem("authToken");

  const SLIDESHOW_IMAGES = [
    "/slides/slide1.png",
    "/slides/slide2.png",
    "/slides/slide3.png",
    "/slides/slide4.png",
    "/slides/slide5.png"
  ];

  const fetchOwnProfile = async () => {
    try {
      const res = await axios.get("http://localhost:8080/api/user/profile", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setPlayerProfiles((prev) => ({ ...prev, self: res.data }));
    } catch (e) {
      console.error("Failed to load own profile:", e);
    }
  };

  const fetchPlayerProfile = async (gameId) => {
    try {
      const res = await axios.get(`http://localhost:8080/api/user/profile/${gameId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return res.data;
    } catch (e) {
      return null;
    }
  };

  const connectWebSocket = () => {
    if (stompClientRef.current) {
      stompClientRef.current.deactivate();
    }

    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        const selfId = playerProfiles.self?.gameId;
        if (selfId) {
          client.subscribe(`/topic/match/${selfId}`, async (message) => {
            const payload = JSON.parse(message.body);

            if (payload.status === "CANCELLED") {
              setStatus("❌ ম্যাচ বাতিল হয়েছে");
              clearInterval(slideshowRef.current);
              clearInterval(countdownRefP1.current);
              clearInterval(countdownRefP2.current);
              setCountdownP1(null);
              setCountdownP2(null);
              return;
            }

            if (payload.player1 && payload.player2) {
              const { player1, player2, startTime } = payload;

              // fetch opponent
              const opponentId = player1 === selfId ? player2 : player1;
              const opponentProfile = await fetchPlayerProfile(opponentId);
              setPlayerProfiles((prev) => ({ ...prev, opponent: opponentProfile }));
              clearInterval(slideshowRef.current);

              // Assume payload.startTime is a timestamp (ms) when match starts + 10 sec countdown
              // Calculate countdown for each player based on current time
              // Here we do a 10 sec countdown for both players (you can adjust logic)

              // Clear existing timers before starting new ones
              clearInterval(countdownRefP1.current);
              clearInterval(countdownRefP2.current);

              // Initialize timers
              let timeLeftP1 = 10;
              let timeLeftP2 = 10;
              setCountdownP1(timeLeftP1);
              setCountdownP2(timeLeftP2);

              countdownRefP1.current = setInterval(() => {
                timeLeftP1 -= 1;
                setCountdownP1(timeLeftP1);
                if (timeLeftP1 <= 0) {
                  clearInterval(countdownRefP1.current);
                }
              }, 1000);

              countdownRefP2.current = setInterval(() => {
                timeLeftP2 -= 1;
                setCountdownP2(timeLeftP2);
                if (timeLeftP2 <= 0) {
                  clearInterval(countdownRefP2.current);
                }
              }, 1000);

              // After countdown finishes, navigate to game
              setTimeout(() => {
                localStorage.setItem("currentSessionId", payload.gameId);
                localStorage.setItem("entryFee", payload.entryFee);
                navigate("/game");
              }, 10 * 1000); // 10 seconds
            }
          });
        }
      },
      onStompError: (frame) => {
        console.error("Broker reported error: " + frame.headers["message"]);
      },
      onWebSocketClose: (evt) => {
        console.log("WebSocket closed: ", evt);
      },
    });
    client.activate();
    stompClientRef.current = client;
  };

  useEffect(() => {
    fetchOwnProfile();
    return () => {
      stompClientRef.current?.deactivate();
      clearInterval(slideshowRef.current);
      clearInterval(countdownRefP1.current);
      clearInterval(countdownRefP2.current);
    };
  }, []);

  const handleMatchRequest = async (fee) => {
    setEntryFee(fee);
    setShowPlayers(true);
    setLoading(true);
    setStatus("⏳ প্রতিপক্ষ খোঁজা হচ্ছে...");
    setPlayerProfiles((prev) => ({ ...prev, opponent: {} }));

    // start avatar slideshow
    slideshowRef.current = setInterval(() => {
      setSlideshowIndex((prev) => (prev + 1) % SLIDESHOW_IMAGES.length);
    }, 1000);

    try {
      await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee: fee },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      connectWebSocket();

    } catch {
      clearInterval(slideshowRef.current);
      setStatus("❌ ম্যাচ শুরু করতে সমস্যা হয়েছে");
      setLoading(false);
    }
  };

  const backToHome = () => {
    stompClientRef.current?.deactivate();
    clearInterval(slideshowRef.current);
    clearInterval(countdownRefP1.current);
    clearInterval(countdownRefP2.current);
    setShowPlayers(false);
    setStatus("");
    setLoading(false);
    setEntryFee(null);
    setPlayerProfiles({ self: playerProfiles.self, opponent: {} });
    setCountdownP1(null);
    setCountdownP2(null);
  };

  const renderAvatar = (profile) => {
    if (profile?.avatarUrl) return `http://localhost:8080${profile.avatarUrl}`;
    if (profile?.displayName)
      return `https://ui-avatars.com/api/?name=${encodeURIComponent(profile.displayName)}`;
    return "/default-avatar.png";
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-indigo-900 via-purple-800 to-indigo-900 p-6">
      <style>{`
        @keyframes pulseBounceGlow {
          0%, 100% {
            transform: scale(1) translateY(0);
            box-shadow: 0 0 15px rgba(255,215,0,0.6), 0 0 30px rgba(255,215,0,0.4);
          }
          50% {
            transform: scale(1.08) translateY(-6px);
            box-shadow: 0 0 30px rgba(255,215,0,1), 0 0 50px rgba(255,215,0,0.9);
          }
        }
        .avatar-anim {
          animation: pulseBounceGlow 1.2s infinite ease-in-out;
          border: 4px solid gold;
        }
      `}</style>

      <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 w-full max-w-md shadow-xl border border-white/20">
        <h2 className="text-3xl font-bold text-center text-white mb-6">🎲 লুডু ম্যাচ</h2>

        {!showPlayers && (
          <>
            <div className="flex flex-col gap-4 mb-4">
              {ALLOWED_FEES.map((fee) => (
                <button
                  key={fee}
                  onClick={() => handleMatchRequest(fee)}
                  disabled={loading}
                  className={`w-full py-3 rounded-lg font-bold text-lg transition-all ${
                    entryFee === fee
                      ? "bg-yellow-400 text-black shadow-lg"
                      : "bg-white/20 text-white hover:bg-white/30"
                  }`}
                >
                  ৳ {fee}
                </button>
              ))}
            </div>
            <button
              onClick={() => navigate("/")}
              className="mt-4 w-full py-2 bg-red-500 hover:bg-red-600 text-white rounded-lg"
            >
              🔙 Back
            </button>
          </>
        )}

        {showPlayers && (
          <>
            <div className="flex justify-around items-center mb-6">
              <div className="flex flex-col items-center">
                <img
                  src={renderAvatar(playerProfiles.self)}
                  alt="self-avatar"
                  className="w-32 h-32 rounded-full avatar-anim"
                />
                <span className="mt-3 text-xl font-bold text-white">
                  {playerProfiles.self?.displayName || "You"}
                </span>
                {/* Show countdown for self */}
                {countdownP1 !== null && (
                  <p className="mt-2 text-yellow-300 font-semibold">
                    ম্যাচ শুরু হতে {countdownP1} সেকেন্ড বাকি...
                  </p>
                )}
              </div>

              <span className="text-yellow-400 text-3xl font-extrabold">VS</span>

              <div className="flex flex-col items-center">
                <img
                  src={
                    playerProfiles.opponent?.displayName
                      ? renderAvatar(playerProfiles.opponent)
                      : SLIDESHOW_IMAGES[slideshowIndex]
                  }
                  alt="opponent-avatar"
                  className="w-32 h-32 rounded-full avatar-anim"
                />
                <span className="mt-3 text-xl font-bold text-white">
                  {playerProfiles.opponent?.displayName || "Waiting..."}
                </span>
                {/* Show countdown for opponent */}
                {countdownP2 !== null && (
                  <p className="mt-2 text-yellow-300 font-semibold">
                    ম্যাচ শুরু হতে {countdownP2} সেকেন্ড বাকি...
                  </p>
                )}
              </div>
            </div>

            {status && <p className="mt-4 text-center text-white font-medium">{status}</p>}

            <button
              onClick={backToHome}
              className="mt-4 w-full py-2 bg-red-500 hover:bg-red-600 text-white rounded-lg"
            >
              🔙 Back
            </button>
          </>
        )}
      </div>
    </div>
  );
}
